import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/webgpu';
import { gsap } from 'gsap';
import { __ } from '@/primitives';
import { __ as __text } from '@/text';

export default function createNode(config, ctx) {
  const { Group: THREEGroup } = ctx.THREE;

  // Root container
  const root = new THREEGroup();

  // Atlas region (fallback to whole texture)
  const atlas = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlas.width / atlas.height;

  // Geometry sized to atlas aspect
  const geometry = new PlaneGeometry(aspect, 1);

  // Node material
  const material = new MeshBasicNodeMaterial();

  // Placeholder texture node (will be set once loaded)
  let texNode = texture(null);
  material.map = texNode;

  // Load the texture asynchronously
  let loadedTexture = null;
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      texNode = texture(tex);
      material.map = texNode;
      material.needsUpdate = true;
    })
    .catch(() => {
      // In case loading fails, keep material empty
    });

  // Mesh that billboards toward the camera
  const mesh = new Mesh(geometry, material);
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  root.add(mesh);

  // Cleanup resources
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
    // No GSAP timelines for this node, but kill any just in case
    gsap.killTweensOf(mesh);
  };

  // Empty handlers placeholder
  root.userData.handlers = {};

  return root;
}
